'use client';
import Link from 'next/link';
import { useMemo, useState } from 'react';
import { ApiError, api } from '@/lib/api';
import { ErrorBox, Loading, useApp, useAsync } from '@/components/app/AppShell';
import { useI18n } from '@/components/Providers';

interface Rec { id: string; code: string | null; data: Record<string, any> }
interface SLine { serviceId: string; qty: number } interface PLine { partId: string; qty: number }
const FLOW: Record<string, string[]> = { open: ['diagnosing', 'in_progress', 'cancelled'], diagnosing: ['awaiting_parts', 'in_progress', 'cancelled'], awaiting_parts: ['in_progress', 'cancelled'], in_progress: ['ready', 'cancelled'], ready: ['delivered'] };
const EDITABLE = ['open', 'diagnosing', 'awaiting_parts'];

/** Auto: the workshop screen. Pick a work order, assign the technician, add services and spare parts (priced and stock-checked by the server), then move it through diagnosis, parts, work, ready and delivery. */
export default function WorkOrders() {
  const app = useApp(); const { locale } = useI18n(); const t = (ar: string, en: string) => (locale === 'ar' ? ar : en); const m = app.money;
  const [status, setStatus] = useState('active'); const [q, setQ] = useState(''); const [tech, setTech] = useState(''); const [sel, setSel] = useState(''); const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null); const [busy, setBusy] = useState(false);
  const get = (e: string, qs = '') => api<Rec[]>(`/tenant/p/${e}?pageSize=100${qs}`).then((r) => r.data);
  const orders = useAsync(() => get('workOrder', `&sort=createdAt&dir=desc${tech ? `&technicianId=${tech}` : ''}${q.trim() ? `&q=${encodeURIComponent(q.trim())}` : ''}`), [tech, q]);
  const vehicles = useAsync(() => get('vehicle').catch(() => [] as Rec[]), []); const techs = useAsync(() => get('technician').catch(() => [] as Rec[]), []); const services = useAsync(() => get('service').catch(() => [] as Rec[]), []); const partsCat = useAsync(() => get('sparePart').catch(() => [] as Rec[]), []);
  const [addS, setAddS] = useState({ id: '', qty: '1' }); const [addP, setAddP] = useState({ id: '', qty: '1' });
  const V = useMemo(() => new Map((vehicles.data ?? []).map((v) => [v.id, `${v.data.plate ?? ''} ${v.data.make ?? ''} ${v.data.model ?? ''}`.trim()])), [vehicles.data]); const T = useMemo(() => new Map((techs.data ?? []).map((x) => [x.id, String(x.data.name)])), [techs.data]);
  const S = useMemo(() => new Map((services.data ?? []).map((x) => [x.id, x])), [services.data]); const P = useMemo(() => new Map((partsCat.data ?? []).map((x) => [x.id, x])), [partsCat.data]);
  if (!app.can('workOrders.read')) return <div className="alert warn" role="alert">{t('لا تملك صلاحية عرض أوامر الشغل.', 'You cannot view work orders.')}</div>;
  if (orders.error) return <ErrorBox error={orders.error} retry={orders.reload} />; if (!orders.data) return <Loading />;
  const shown = orders.data.filter((o) => (status === 'all' ? true : status === 'active' ? !['delivered', 'cancelled'].includes(String(o.data.status)) : o.data.status === status)); const wo = orders.data.find((o) => o.id === sel);
  const patch = async (body: object, ok: string) => { setBusy(true); setMsg(null); try { await api(`/tenant/p/workOrder/${sel}`, { method: 'PATCH', body }); setMsg({ ok: true, text: ok }); orders.reload(); } catch (e) { setMsg({ ok: false, text: (e as ApiError).message }); } finally { setBusy(false); } };
  const stLabel = (s: string) => ({ open: t('جديد', 'Open'), diagnosing: t('فحص', 'Diagnosing'), awaiting_parts: t('بانتظار قطع', 'Awaiting parts'), in_progress: t('قيد التنفيذ', 'In progress'), ready: t('جاهز', 'Ready'), delivered: t('تم التسليم', 'Delivered'), cancelled: t('ملغي', 'Cancelled') } as Record<string, string>)[s] ?? s;
  const editable = wo ? EDITABLE.includes(String(wo.data.status)) && app.can('workOrders.update') : false; const sl = (wo?.data.services as SLine[]) ?? []; const pl = (wo?.data.parts as PLine[]) ?? [];
  return (
    <>
      <div className="row between"><h1 style={{ fontSize: '1.6rem', margin: 0 }}>{t('أوامر الشغل', 'Work orders')}</h1>{app.can('workOrders.create') && <Link className="btn primary" href="/app/e/workOrder/new">{t('أمر شغل جديد', 'New work order')}</Link>}</div>
      {msg && <div className={`alert ${msg.ok ? 'ok' : 'error'}`} role="alert">{msg.text}</div>}
      <div className="row" style={{ flexWrap: 'wrap' }}><input type="search" aria-label={t('بحث بالشكوى', 'Search complaint')} placeholder={t('بحث بالشكوى', 'Search complaint')} value={q} onChange={(e) => setQ(e.target.value)} style={{ maxWidth: 260 }} />
        <select aria-label={t('الفني', 'Technician')} value={tech} onChange={(e) => setTech(e.target.value)} style={{ width: 'auto' }}><option value="">{t('كل الفنيين', 'All technicians')}</option>{(techs.data ?? []).map((x) => <option key={x.id} value={x.id}>{x.data.name}</option>)}</select>
        <div className="row" role="tablist" aria-label={t('الحالة', 'Status')} style={{ flexWrap: 'wrap' }}>{['active', 'open', 'diagnosing', 'awaiting_parts', 'in_progress', 'ready', 'delivered', 'all'].map((s) => <button key={s} role="tab" aria-selected={status === s} className={`btn sm ${status === s ? 'primary' : ''}`} onClick={() => setStatus(s)}>{s === 'active' ? t('النشطة', 'Active') : s === 'all' ? t('الكل', 'All') : stLabel(s)}</button>)}</div></div>
      <div className="grid g2" style={{ alignItems: 'start' }}>
        <section className="card stack"><h3>{shown.length} {t('أمر', 'orders')}</h3>{!shown.length ? <p className="muted">{t('لا توجد أوامر شغل.', 'No work orders.')}</p> : shown.map((o) => <button key={o.id} type="button" className={`card flat stack ${sel === o.id ? 'selected' : ''}`} aria-pressed={sel === o.id} onClick={() => { setSel(o.id); setMsg(null); }} style={{ textAlign: 'start', cursor: 'pointer', outline: sel === o.id ? '2px solid var(--color-primary)' : undefined }}>
          <div className="row between"><b className="mono">{o.code}</b><span className="badge">{stLabel(String(o.data.status))}</span></div><span>{V.get(String(o.data.vehicleId)) ?? ''}</span><span className="small muted">{String(o.data.complaint).slice(0, 90)}{o.data.technicianId ? ` · ${T.get(String(o.data.technicianId)) ?? ''}` : ''}</span></button>)}</section>
        {wo ? <section className="card stack" aria-label={t('تفاصيل أمر الشغل', 'Work order details')}>
          <div className="row between"><h3 style={{ margin: 0 }}>{wo.code} · {V.get(String(wo.data.vehicleId))}</h3><span className="badge">{stLabel(String(wo.data.status))}</span></div><p style={{ margin: 0, whiteSpace: 'pre-wrap' }}>{String(wo.data.complaint)}</p>
          <label className="field">{t('الفني المسؤول', 'Technician')}<select value={String(wo.data.technicianId ?? '')} disabled={busy || !app.can('workOrders.update') || !EDITABLE.concat('in_progress').includes(String(wo.data.status))} onChange={(e) => e.target.value && patch({ technicianId: e.target.value }, t('تم تعيين الفني.', 'Technician assigned.'))}><option value="">—</option>{(techs.data ?? []).map((x) => <option key={x.id} value={x.id}>{x.data.name}</option>)}</select></label>
          <div className="table-wrap"><table><caption className="sr-only">{t('الخدمات', 'Services')}</caption><thead><tr><th scope="col">{t('الخدمة', 'Service')}</th><th scope="col">{t('الكمية', 'Qty')}</th><th scope="col">{t('السعر', 'Price')}</th><th /></tr></thead><tbody>{!sl.length && <tr><td colSpan={4} className="muted">{t('لا توجد خدمات', 'No services')}</td></tr>}{sl.map((l, i) => <tr key={i}><td>{S.get(l.serviceId)?.data.name ?? l.serviceId}</td><td>{l.qty}</td><td className="mono">{m(Number(S.get(l.serviceId)?.data.price ?? 0) * l.qty)}</td><td>{editable && <button className="btn sm danger" disabled={busy} aria-label={t('حذف', 'Remove')} onClick={() => patch({ services: sl.filter((_, n) => n !== i) }, t('تم الحذف.', 'Removed.'))}>✕</button>}</td></tr>)}</tbody></table></div>
          {editable && <div className="row"><select aria-label={t('إضافة خدمة', 'Add service')} value={addS.id} onChange={(e) => setAddS({ ...addS, id: e.target.value })}><option value="">+ {t('خدمة', 'Service')}</option>{(services.data ?? []).map((x) => <option key={x.id} value={x.id}>{x.data.name}</option>)}</select><input type="number" min={1} aria-label={t('الكمية', 'Qty')} value={addS.qty} onChange={(e) => setAddS({ ...addS, qty: e.target.value })} style={{ width: 80 }} /><button className="btn sm" disabled={busy || !addS.id} onClick={() => { patch({ services: [...sl, { serviceId: addS.id, qty: Number(addS.qty) || 1 }] }, t('تمت إضافة الخدمة.', 'Service added.')); setAddS({ id: '', qty: '1' }); }}>{t('إضافة', 'Add')}</button></div>}
          <div className="table-wrap"><table><caption className="sr-only">{t('قطع الغيار', 'Spare parts')}</caption><thead><tr><th scope="col">{t('القطعة', 'Part')}</th><th scope="col">{t('الكمية', 'Qty')}</th><th scope="col">{t('المخزون', 'Stock')}</th><th scope="col">{t('السعر', 'Price')}</th><th /></tr></thead><tbody>{!pl.length && <tr><td colSpan={5} className="muted">{t('لا توجد قطع', 'No parts')}</td></tr>}{pl.map((l, i) => { const p = P.get(l.partId); return <tr key={i}><td>{p?.data.name ?? l.partId}</td><td>{l.qty}</td><td><span className={`badge ${Number(p?.data.stock ?? 0) >= l.qty ? 'ok' : 'bad'}`}>{p?.data.stock ?? 0}</span></td><td className="mono">{m(Number(p?.data.price ?? 0) * l.qty)}</td><td>{editable && <button className="btn sm danger" disabled={busy} aria-label={t('حذف', 'Remove')} onClick={() => patch({ parts: pl.filter((_, n) => n !== i) }, t('تم الحذف.', 'Removed.'))}>✕</button>}</td></tr>; })}</tbody></table></div>
          {editable && <div className="row"><select aria-label={t('إضافة قطعة', 'Add part')} value={addP.id} onChange={(e) => setAddP({ ...addP, id: e.target.value })}><option value="">+ {t('قطعة', 'Part')}</option>{(partsCat.data ?? []).map((x) => <option key={x.id} value={x.id}>{x.data.name} ({x.data.stock ?? 0})</option>)}</select><input type="number" min={1} aria-label={t('الكمية', 'Qty')} value={addP.qty} onChange={(e) => setAddP({ ...addP, qty: e.target.value })} style={{ width: 80 }} /><button className="btn sm" disabled={busy || !addP.id} onClick={() => { patch({ parts: [...pl, { partId: addP.id, qty: Number(addP.qty) || 1 }] }, t('تمت إضافة القطعة.', 'Part added.')); setAddP({ id: '', qty: '1' }); }}>{t('إضافة', 'Add')}</button></div>}
          <dl className="grid g4" style={{ margin: 0 }}>{([[t('العمالة', 'Labour'), wo.data.laborTotal], [t('القطع', 'Parts'), wo.data.partsTotal], [t('الضريبة', 'Tax'), wo.data.tax], [t('الإجمالي', 'Total'), wo.data.total]] as [string, unknown][]).map(([k, v]) => <div key={k}><dt className="small muted">{k}</dt><dd className="mono" style={{ margin: 0 }}><b>{m(Number(v ?? 0))}</b></dd></div>)}</dl>
          {app.can('workOrders.update') && (FLOW[String(wo.data.status)] ?? []).length > 0 && <div className="row" style={{ flexWrap: 'wrap' }}>{FLOW[String(wo.data.status)].map((n) => <button key={n} className={`btn ${n === 'cancelled' ? 'danger' : 'primary'}`} disabled={busy} onClick={() => { if (n === 'cancelled' && !window.confirm(t('إلغاء أمر الشغل؟', 'Cancel this work order?'))) return; void patch({ status: n }, `${wo.code} → ${stLabel(n)}`); }}>{stLabel(n)}</button>)}</div>}
          <Link className="btn sm" href={`/app/e/workOrder/${wo.id}`}>{t('كل التفاصيل والفاتورة', 'Full record & invoice')}</Link>
        </section> : <section className="card" style={{ textAlign: 'center' }}><p className="muted">{t('اختر أمر شغل من القائمة.', 'Choose a work order from the list.')}</p></section>}
      </div>
    </>
  );
}
